/**
 * Enumeration of blockchains that support Borrow Kit's loan operations
 * (open, borrow, repay, close, add/withdraw collateral, reward claims,
 * webhook registration).
 *
 * Distinct from {@link EarnChain}: Borrow Kit shares its reward-claiming
 * implementation with Earn Kit, but its loan chain support is its own and
 * now includes Arc mainnet, which Earn Kit does not.
 *
 * @example
 * ```typescript
 * import { BorrowChain } from '@core/chains'
 *
 * const result = await borrowKit.borrow({
 *   from: { adapter, chain: BorrowChain.Arc },
 *   marketId: '0x...',
 *   borrowAmount: '100',
 * })
 * ```
 */
declare enum BorrowChain {
    Arc = "Arc",
    Arc_Testnet = "Arc_Testnet"
}

/**
 * Arc Mainnet chain definition
 * @remarks
 * This represents the official production network for the Arc blockchain,
 * Circle's EVM-compatible Layer-1 designed for stablecoin finance
 * and asset tokenization. Arc uses USDC as the native gas token and
 * features the Malachite Byzantine Fault Tolerant (BFT) consensus
 * engine for sub-second finality.
 */
